#include <iostream>
using std::cin;
using std::cout;
using std::cerr;
using std::endl;
#include <string>
using std::string;
#include <map>
using std::map;

int main (void) {
	int q;
	cin >> q;

	map<string, int> accounts;
	int idmax = 0;
	for (int qi = 0; qi < q; qi++) {
		string s;
		cin >> s;

		int ans;
		if (accounts.contains(s)) {
			ans = accounts[s];
		} else {
			ans = accounts[s] = ++idmax;
		}

		cout << ans << "\n";
	}

	return 0;
}
